// Full classification snapshot: every clause on prod -> its class (or NULL).
// Diff two runs to prove a classifier widening moved ONLY the clauses intended and silently
// re-classed nothing else. The module path is an argument so the SAME harness can be pointed at a
// pre-change copy of the engine (git show HEAD:src/lib/sowEngine.js) and at the working tree — a
// baseline generated by a different script would be measuring two things at once.
// Usage: node scripts/snapshot-clause-classes.mjs <dump.json> [moduleSpecifier]
import { readFileSync } from 'node:fs';

const mod = await import(process.argv[3] ?? '../src/lib/sowEngine.js');
const { splitClauses, classifyClause } = mod;

const rows = JSON.parse(readFileSync(process.argv[2], 'utf8')).filter((r) => r.direct_sow_timing);
const out = [];
for (const r of rows) {
  for (const clause of splitClauses(r.direct_sow_timing)) {
    out.push(`${classifyClause(clause).cls ?? 'NULL'}\t${r.variety_name}\t${clause}`);
  }
}
out.sort();
console.log(out.join('\n'));
